import{_ as n,o as s,c as e,a2 as l}from"./chunks/framework.XXezeKOl.js";const g=JSON.parse('{"title":"Tree of Thoughts","description":"精读 Tree of Thoughts：把单条推理链扩展成一棵可以探索、评估和回溯的思维树，用搜索解决需要试错的问题。","frontmatter":{"title":"Tree of Thoughts","description":"精读 Tree of Thoughts：把单条推理链扩展成一棵可以探索、评估和回溯的思维树，用搜索解决需要试错的问题。"},"headers":[],"relativePath":"papers/tree-of-thoughts.md","filePath":"papers/tree-of-thoughts.md","lastUpdated":null}'),t={name:"papers/tree-of-thoughts.md"};function i(r,a,o,p,h,u){return s(),e("div",null,[...a[0]||(a[0]=[l(`<h1 id="tree-of-thoughts" tabindex="-1">Tree of Thoughts <a class="header-anchor" href="#tree-of-thoughts" aria-label="Permalink to &quot;Tree of Thoughts&quot;">​</a></h1><h2 id="论文信息" tabindex="-1">论文信息 <a class="header-anchor" href="#论文信息" aria-label="Permalink to &quot;论文信息&quot;">​</a></h2><ul><li>标题：Tree of Thoughts: Deliberate Problem Solving with Large Language Models</li><li>作者：Shunyu Yao、Dian Yu、Jeffrey Zhao、Izhak Shafran、Thomas L. Griffiths、Yuan Cao、Karthik Narasimhan（Princeton University、Google DeepMind）</li><li>年份：2023（NeurIPS 2023）</li><li>链接：<a href="https://arxiv.org/abs/2305.10601" target="_blank" rel="noreferrer">arXiv:2305.10601</a></li></ul><h2 id="一句话总结" tabindex="-1">一句话总结 <a class="header-anchor" href="#一句话总结" aria-label="Permalink to &quot;一句话总结&quot;">​</a></h2><p>把推理过程拆成一个个&quot;思维步骤&quot;，在每一步生成多个候选，让模型自己评估哪些候选更有希望，再用广度优先或深度优先搜索探索、剪枝和回溯，解决思维链一条路走到底解决不了的问题。</p><h2 id="要解决的问题" tabindex="-1">要解决的问题 <a class="header-anchor" href="#要解决的问题" aria-label="Permalink to &quot;要解决的问题&quot;">​</a></h2><p><a href="/papers/chain-of-thought">Chain-of-Thought</a> 让模型一步一步推理，但它本质上还是从左到右逐 Token 生成，一旦早期某一步走错，后面就很难纠正。</p><p>人类解决难题时并不是这样：我们会考虑几种思路，评估哪种更可行，发现死路后退回来换一种。作者希望让模型也具备这种&quot;有意识的规划和搜索&quot;能力，尤其针对需要探索、前几步决策影响很大的任务。</p><h2 id="核心方法" tabindex="-1">核心方法 <a class="header-anchor" href="#核心方法" aria-label="Permalink to &quot;核心方法&quot;">​</a></h2><p>ToT 把问题求解建模为在一棵&quot;思维树&quot;上的搜索，需要设计四个部分：</p><ol><li><strong>思维分解：</strong> 定义一个&quot;思维步骤&quot;的粒度，比如一个算式、一段写作计划、填一个单词。</li><li><strong>思维生成：</strong> 在每个节点，让模型生成若干个候选的下一步。</li><li><strong>状态评估：</strong> 让模型给每个候选打分（比如&quot;确定可行 / 可能 / 不可能&quot;），或在多个候选中投票。</li><li><strong>搜索算法：</strong> 用 BFS（每层保留最好的若干个）或 DFS（沿最有希望的分支深入，不行就回溯）。</li></ol><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>                         问题</span></span>
<span class="line"><span>                          │</span></span>
<span class="line"><span>           ┌──────────────┼──────────────┐</span></span>
<span class="line"><span>           ▼              ▼              ▼</span></span>
<span class="line"><span>        思路 A          思路 B          思路 C        ◀── 生成多个候选</span></span>
<span class="line"><span>       评估:可能        评估:确定        评估:不可能     ◀── 模型自评</span></span>
<span class="line"><span>           │              │              ✗ 剪枝</span></span>
<span class="line"><span>      ┌────┴────┐     ┌───┴────┐</span></span>
<span class="line"><span>      ▼         ▼     ▼        ▼</span></span>
<span class="line"><span>     A1        A2    B1       B2</span></span>
<span class="line"><span>   不可能     可能   确定     可能</span></span>
<span class="line"><span>     ✗         │     │</span></span>
<span class="line"><span>               …     ▼</span></span>
<span class="line"><span>                    答案  ◀── 找到可行解；若走入死路则回溯到上一层</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  对比：Chain-of-Thought 只有一条路径   问题 ──▶ 步骤1 ──▶ 步骤2 ──▶ 答案</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br></div></div><p>生成和评估都由同一个大模型通过不同的提示词完成，不需要训练任何额外模型。</p><h2 id="关键实验结论" tabindex="-1">关键实验结论 <a class="header-anchor" href="#关键实验结论" aria-label="Permalink to &quot;关键实验结论&quot;">​</a></h2><p>论文设计了三个需要规划或搜索的任务：24 点游戏（用四个数字和四则运算得到 24）、创意写作（写出结尾句子给定的连贯段落）、迷你填字游戏。</p><ul><li><strong>24 点游戏：</strong> 这是提升最明显的任务。标准提示和思维链的成功率很低，ToT 将成功率提升到了大多数题目都能解出的水平。原因是 24 点的早期选择错误后很难挽回，而 ToT 可以评估并剪掉不可能的分支。</li><li><strong>创意写作：</strong> 人工和模型评估都认为 ToT 生成的文章更连贯，但提升幅度比 24 点小。</li><li><strong>填字游戏：</strong> 使用 DFS 加回溯后，单词和整题的完成率都明显高于思维链。消融实验显示，去掉剪枝或回溯，效果都会下降。</li><li><strong>代价：</strong> ToT 需要的模型调用次数和 Token 数远多于思维链。</li></ul><h2 id="对-agent-开发的启发" tabindex="-1">对 Agent 开发的启发 <a class="header-anchor" href="#对-agent-开发的启发" aria-label="Permalink to &quot;对 Agent 开发的启发&quot;">​</a></h2><ul><li><strong>&quot;生成多个候选再选择&quot;是通用模式。</strong> 不一定要完整实现树搜索，在关键决策点生成几个方案、让模型或规则评估后再执行，往往就能带来收益。</li><li><strong>评估器是核心。</strong> ToT 的效果取决于模型能否准确判断&quot;这条路有没有希望&quot;。在 Agent 中，能用确定性规则（测试、校验、计算）评估的地方，尽量不要只依赖模型自评。</li><li><strong>为任务选择合适的控制流。</strong> 大多数 Agent 任务用 <a href="/papers/react">ReAct</a> 或 <a href="/guide/06-agent-loop/plan-execute">Plan-and-Execute</a> 就够了；只有在&quot;早期决策影响大、需要试错&quot;的任务上，搜索类方法才值得它的成本。</li><li><strong>推理模型在一定程度上内化了这一思路。</strong> 今天的推理模型在内部也会探索和自我修正，很多场景下直接使用推理模型比手写树搜索更简单。</li></ul><h2 id="局限性" tabindex="-1">局限性 <a class="header-anchor" href="#局限性" aria-label="Permalink to &quot;局限性&quot;">​</a></h2><ul><li>成本高：每一步都要生成多个候选并逐个评估，调用次数成倍增长，延迟也高。</li><li>需要针对任务手工设计思维粒度、评估提示词和搜索策略，通用性有限。</li><li>评估依赖模型自身判断，模型评估错误会导致剪掉正确分支。</li><li>实验任务偏向谜题类，在开放的真实任务中效果还需要验证。</li><li>对于模型本来就擅长的任务，搜索带来的收益很小。</li></ul><h2 id="相关文章" tabindex="-1">相关文章 <a class="header-anchor" href="#相关文章" aria-label="Permalink to &quot;相关文章&quot;">​</a></h2><ul><li><a href="/guide/04-prompt/few-shot-cot">Few-shot 与思维链</a></li><li><a href="/guide/02-llm-basics/reasoning-models">推理模型与扩展思考</a></li><li><a href="/guide/06-agent-loop/plan-execute">Plan-and-Execute</a></li><li><a href="/guide/06-agent-loop/reflection">Reflection 自我反思</a></li><li><a href="/guide/15-production/cost-optimization">成本与延迟优化</a></li></ul>`,22)])])}const d=n(t,[["render",i]]);export{g as __pageData,d as default};
